final class QuestionExplanationExecution { /** @param array<string,mixed>|null $result */ public function __construct(public readonly string $id,public readonly string $userId,public readonly string $questionId,public readonly ?string $attemptId,public readonly string $algorithmVersion,public readonly ExplanationSafetyMode $safetyMode,private ExplanationStatus $status,private int $retryCount,private ?string $provider,private ?string $model,private ?int $tokenCount,private ?int $durationMilliseconds,private ?array $result,private ?string $errorCode,private ?string $errorMessage,public readonly \DateTimeImmutable $requestedAt,private ?\DateTimeImmutable $startedAt=null,private ?\DateTimeImmutable $completedAt=null) {} public function status():ExplanationStatus{return $this->status;}public function retryCount():int{return $this->retryCount;}public function provider():?string{return $this->provider;}public function model():?string{return $this->model;}public function tokenCount():?int{return $this->tokenCount;}public function durationMilliseconds():?int{return $this->durationMilliseconds;}public function result():?array{return $this->result;}public function errorCode():?string{return $this->errorCode;}public function errorMessage():?string{return $this->errorMessage;}public function startedAt():?\DateTimeImmutable{return $this->startedAt;}public function completedAt():?\DateTimeImmutable{return $this->completedAt;}public function begin(\DateTimeImmutable $now):void{$this->status=ExplanationStatus::PROCESSING;$this->startedAt=$now;}public function complete(array $result,string $provider,string $model,?int $tokens,?int $durationMs,\DateTimeImmutable $now):void{$this->status=ExplanationStatus::COMPLETED;$this->result=$result;$this->provider=$provider;$this->model=$model;$this->tokenCount=$tokens;$this->durationMilliseconds=$durationMs;$this->completedAt=$now;}public function fail(string $code,string $message,\DateTimeImmutable $now):void{$this->status=ExplanationStatus::FAILED;$this->retryCount++;$this->errorCode=$code;$this->errorMessage=$message;$this->completedAt=$now;}}
